// Código para N8N - Code Node
// Filtra apenas instâncias com connectionStatus "open"
// Exclui ownerJid que contém: 984698653, 984074247, 985685106
// e extrai os campos: name, ownerJid e token

const inputData = $input.all();
const result = [];

// Lista de números a serem excluídos (apenas os dígitos relevantes)
const excludedNumbers = ['84698653', '84074247', '85685106'];

// Processa cada item de entrada
inputData.forEach(item => {
  const data = item.json;

  // Verifica se é um array ou objeto único
  const items = Array.isArray(data) ? data : [data];

  // Filtra e mapeia os dados
  items.forEach(instance => {
    // Verifica se o connectionStatus é "open"
    if (instance.connectionStatus === "open") {
      // Verifica se o ownerJid NÃO contém nenhum dos números excluídos
      const shouldExclude = excludedNumbers.some(num => 
        instance.ownerJid && instance.ownerJid.includes(num)
      );

      // Se não deve excluir, adiciona ao resultado
      if (!shouldExclude) {
        result.push({
          name: instance.name,
          ownerJid: instance.ownerJid,
          token: instance.token
        });
      }
    }
  });
});

// Retorna os dados filtrados
return result.map(item => ({ json: item }));

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

