const body = $input.item.json.body;
if(!body) return { json: { success: false } };
let nums = [];
if(body.numeros) nums = body.numeros.split(',').map(n => n.trim()).filter(n => n);

const items = nums.map(n => ({
  json: { 
    remoteJid: n,
    mensagem: body.mensagem,
    horaMax: body.horaMax,
    delay: body.delay
  }
}));
return items;
